from __future__ import annotations

from .cart import Cart


def format_cents(cents: int) -> str:
    return f"${cents // 100}.{cents % 100:02d}"


def render_receipt(cart: Cart) -> str:
    lines = []
    for item in cart.items:
        amount = format_cents(item.price_cents * item.quantity)
        lines.append(f"{item.quantity} x {item.name:<20} {amount:>10}")
    lines.append(f"{'Subtotal':<25} {format_cents(cart.subtotal_cents()):>10}")
    return "\n".join(lines)
